INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dhurandhar_2025', 'Dhurandhar received mixed reviews from critics.', -0.296, 'neg', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dhurandhar_2025', 'Trade analyst Taran Adarsh gave 4.5/5 stars and described the film as a "brilliant" and "power-packed" action spectacle, citing its strong storytelling and box-office appeal.', 0.7964, 'pos', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dhurandhar_2025', 'Gayatri Nirmal of Pinkvilla gave 4/5 stars and praised the second-half, screenplay, and background score but criticised the runtime.', -0.3818, 'neg', 'music');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dhurandhar_2025', 'Siddhant Adlakha of IGN rated the film 8/10 stars and wrote "Bollywood gangster saga Dhurandhar walks a fine line between raucous entertainment and hateful propaganda." 
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dhurandhar_2025', 'She highlighted the film''s immersive world-building, the gritty, violent underworld of Karachi''s Lyari mafia through a narrative structured in multiple chapters, with a runtime of nearly three-and-a-half hours that nevertheless "rarely feels overbearing", owing to what is described as "stylish, tight storytelling."
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dhurandhar_2025', 'Rishabh Suri of Hindustan Times gave 3/5 stars and described it as a "lengthy yet loaded spy drama", highlighting the performances of Ranveer Singh and Akshaye Khanna as well Aditya Dhar''s direction.', 0.2732, 'pos', 'acting');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dhurandhar_2025', 'He also noted the film occasionally feels too long and dense with too many sub-plots.', 0, 'neu', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dhurandhar_2025', 'Radhika Sharma of NDTV gave 3/5 stars and praised the cast performances and soundtrack, but criticised the second half calling it "a completely different film altogether." Taher Ahmed of Deccan Herald gave 3/5 stars and praised the performances, cinematography, and soundtrack, but criticised the runtime, pacing, and climax.', -0.25, 'neg', 'music');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dhurandhar_2025', 'Simran Khan of Times Now gave 3/5 stars and wrote "The Aditya Dhar actioner''s ending doesn''t quite justify its lengthy runtime.', 0, 'neu', 'vfx_action');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dhurandhar_2025', 'However the adrenaline-pumping set pieces and relentless high-voltage action, paired with a background score that amplifies the drama and keeps the tension from ever dipping, make the ride worth it." Karthik Ravindranath of The Week gave 3/5 stars and wrote "The film''s powerful core is diluted by overt jingoism, unnecessary elements, and a tendency to dumb down its message for the audience.', -0.1779, 'neg', 'music');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dhurandhar_2025', 'Despite these irritants, it remains a largely engaging, albeit flawed, tribute to India''s heroes." Vineeta Kumar of India Today gave 3/5 stars and wrote "Dhurandhar is a sprawling, muscular, politically sharp thriller that bites off a lot, and thanks to Khanna''s explosive brilliance, chews most of it successfully."
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dhurandhar_2025', 'But then two hours have passed and the ace seems to be still far up its sleeves." Deepa Gahlot of Rediff.com gave 2.5/5 stars and wrote "Dhurandhar may not have the dark realism of a spy story, which a web show can manage.', 0, 'neu', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dhurandhar_2025', 'But it does not have the flamboyance either that has come to be associated with espionage movies." 
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dhurandhar_2025', 'She praised the film''s scale, production values, and the attempt to depict the many layers of Lyari''s criminal, political, and familial dynamics.', 0.5574, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dhurandhar_2025', 'However, she argued that despite its large cast and multiple narrative strands, the film only intermittently comes together, with its storytelling lacking consistency.', -0.3612, 'neg', 'acting');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dhurandhar_2025', 'Sakhi Thirani of Common Sense Media gave 1/5 stars and wrote "Despite dealing with sensitive issues like terrorism and war, Dhurandhar lacks a sincere or thoughtful storyline.', -0.4019, 'neg', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dhurandhar_2025', 'Instead, it''s more concerned with romanticizing torture, aggression, and machismo without examining the consequences of such violence." Sadanand Dhume of The Wall Street Journal wrote "Dhurandhar is the first major Bollywood movie to realistically portray the terrorist threat India faces." Columnist Shobhaa De wrote "It''s not about politics.', -0.9504, 'neg', 'acting');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dhurandhar_2025', 'It''s about a story – perhaps fictionalised. ...', 0, 'neu', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dhurandhar_2025', 'I won''t mind watching it all over again.', 0, 'neu', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dhurandhar_2025', 'Yes, three and a half hours of it." Nandini Ramnath of Scroll.in wrote "A considerable stretch of the staggering 214-minute film is no different from gangland chronicles led by swaggering, aphorism-dripping men.', 0.128, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dhurandhar_2025', 'Hamza''s rise to the top of the Karachi underworld is soaked in blood and cliche".', 0.2023, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dhurandhar_2025', 'Athulya Nambiar of Mid-Day wrote "It''s too soon to judge Dhurandhar as a good or bad film, simply because the story isn''t complete yet." Anuj Kumar of The Hindu wrote "Moored by a charismatic Akshaye Khanna and a brooding Ranveer Singh, Aditya Dhar''s ambitious but overstretched and chest-thumping espionage saga serves political interests, tests endurance." Rahul Desai of The Hollywood Reporter India wrote "Aditya Dhar''s second film after Uri: The Surgical Strike stars Ranveer Singh as a patriotic spy trapped in an inert and distracted action thriller." Uday Bhatia of Mint wrote "Dhurandhar offers sadism and expert bad vibes and it shares something else fundamental with Dhar''s previous work—it''s propaganda in service of a hawkish India, designed to flatter the ruling BJP leadership."', -0.8555, 'neg', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('chhaava_2025', 'Prasanna Zore of Rediff rated the film 4 out of 5, writing "Chhaava deserves 2 stars for the historically half-baked film that it is, but 4 stars just for its attempt on making a film on Chhatrapati Sambhaji Maharaj." Zee News gave 4 stars out of 5 stars and wrote "Chhaava is much more than just an action-packed period drama; it''s a film that resonates with its historical significance while maintaining its emotional core." Pooja Biraia of The Week rated 3.5 stars out of 5 stars and wrote "The film showcases regality and grandeur, adrenaline-pumping action sequences and punchy dialogues, but interestingly, it does all of that and more, while ensuring it doesn''t lose track of the plot and the narrative that runs beautifully across all its frames."
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('chhaava_2025', 'Kusumika Das of Times Now awarded 3.5 stars out of 5 stars and wrote "While Utekar’s storytelling could have been tighter, his attempt is commendable.', 0.4019, 'pos', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('chhaava_2025', 'Most notably, Chhaava unveils a fierce, unrelenting Vicky Kaushal in a historical saga." Renuka Vyavahare of The Times of India have 3.5 stars out of 5 stars and wrote "Chhaava’s excellence lies in its gripping second half and a terrific climax." Devesh Sharma of Filmfare rated 3.5 stars out of 5 stars and noted that Chhaava succeeds in delivering a high-intensity action film, anchored by Vicky Kaushal''s powerhouse performance.', 0.8225, 'pos', 'acting');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('chhaava_2025', 'However, he pointed out that the film doesn''t fully delve into the complexities of Sambhaji''s character, leaving much of his multifaceted legacy unexplored.', 0, 'neu', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('chhaava_2025', 'Baradwaj Rangan wrote for Galatta Plus, "Chhaava is not exactly a misfire, but it doesn’t rise above being watchable...There are attempts to get into the psyche of Sambhaji with surrealistic nightmares that show the king as a lost little boy with philosophical questions.', -0.4497, 'neg', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('chhaava_2025', 'We get quiet, intimate scenes that show Sambhaji yearning for his mother who died when he was very young.', -0.4767, 'neg', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('chhaava_2025', 'But this sort of delicacy doesn’t fit in with the ethos of a “mass” movie that wants to show Sambhaji as a superhero. “Mass” movies usually work best when they aim low and deliver highs..Chhaava, to its credit, aims high.', 0.8957, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('chhaava_2025', 'But it doesn''t come together satisfactorily.', -0.4168, 'neg', 'acting');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('chhaava_2025', 'What we end up with is a violent showcase for two fine actors." Shubhra Gupta of The Indian Express, gave 2.5 out of 5 rating and wrote "Vicky Kaushal is fully committed in Laxman Utekar’s ultra-loud, ultra-violent, and exhausting film." Saibal Chatterjee of NDTV gave 2.5 stars out of 5 and said that "The film, has far greater depth than the top-heavy treatment that it deploys India order to pay tribute to Chhatrapati Sambhaji Maharaj." Pratikshya Mishra of The Quint gave it 2.5 stars and commented that "Unlike its protagonist, who often runs into battle like a man possessed even when the odds seem stacked against him, the film simply wasn’t brave enough to take that leap." Tushar Joshi of India Today wrote, "Chhaava doesn''t aim to be exceptionally different, but it masters the art of navigating the mainstream waters without completely drowning in the cacophony of its own voice." He rated the film 3 out of 5.', 0.1522, 'pos', 'acting');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('chhaava_2025', 'Rahul Desai of The Hollywood Reporter India observed that "Chhaava is neither romanticised nor pulpy.', -0.3089, 'neg', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('chhaava_2025', 'So scared that only gods and demons can afford to exist.', -0.4927, 'neg', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('chhaava_2025', 'So scared that it’s blinded by its own reflection." Anuj Kumar of The Hindu said that "Struggling to choose between history and the current nationalist sentiment, Laxman Utekar’s unsurprising narrative finds its voice in the final." Nandini Ramnath of Scroll.in said in her review that "Laxman Utekar takes us through every bit of this ordeal – it’s what Chhaava has been building up to.', -0.7178, 'neg', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('chhaava_2025', 'The Christ-like imagery is apposite, given the all-round love for medieval punishment.', 0.25, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('chhaava_2025', 'But the film’s lack of feeling is vivid too, with shouty speechifying mistaken for heartfelt passion and sumptuous visuals confused for grandeur."', 0.7876, 'pos', 'vfx_action');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('saiyaara_2025', 'The film received generally positive reviews from critics, with the lead performances and soundtrack garnering the most praise.', 0.7425, 'pos', 'music');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('saiyaara_2025', 'Bollywood Hungama gave 4 out of 5 stars and described it as "a stirring musical saga" that was elevated by Mohit Suri''s deft direction, heartfelt romance, chart-topping music, and the stellar performances of its debutant leads.', 0.7964, 'pos', 'music');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('saiyaara_2025', 'Rishabh Suri of the Hindustan Times gave 3.5/5 stars and opined that while the story did not break new ground, it struck the right emotional chords, understood its audience, and delivered with sincerity, adding that "sometimes, that is more than enough".', -0.1027, 'neg', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('saiyaara_2025', 'Vineeta Kumar of India Today gave 3.5/5 stars and found the film entertaining, emotional, and musical: a cinematic piece where the flaws were visible but the heart shone through.', 0.8422, 'pos', 'music');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('saiyaara_2025', 'Other critics were more reserved, pointing out the familiar storyline and uneven pacing.', -0.296, 'neg', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('saiyaara_2025', 'Radhika Sharma of NDTV gave 3/5 stars, summarising the plot as "as old as time": a bad boy meets a good girl, sparks fly, heartbreak and sacrifice follow, and then a reunion, but acknowledged Mohit Suri''s strong command over heartbreak.', -0.5023, 'neg', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('saiyaara_2025', 'Vinamra Mathur of Firstpost gave 3/5 stars and noted that while the love story was messy and imperfect, the lead actors sailed through it with conviction.', 0.1027, 'pos', 'acting');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('saiyaara_2025', 'Kusumika Das of Times Now gave 2.5/5 stars and felt the film aimed for the stars but only touched the clouds; the soul of the film lay in the performances, with occasional flashes of classic Mohit Suri magic in lines like "Mera na hona, tumhare bade hone ka wajah banega".', 0.5023, 'pos', 'acting');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('saiyaara_2025', 'Aishwarya Vasudevan of OTTplay gave 3/5 stars and wrote that the film "doesn’t reinvent the wheel of romance, but it sure makes it spin with heart", and praised the harmony between the two lead actors.', 0.9559, 'pos', 'acting');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('saiyaara_2025', 'Jaya Dwivedie of India TV gave 3/5 stars and described the film as a slow-paced love story that tried to reach the audience''s hearts despite its unfamiliarity and incompleteness.', 0.8625, 'pos', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('war_2_2025', 'War 2 received mixed-to-negative reviews from critics and audiences.', -0.7269, 'neg', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('war_2_2025', 'Dhaval Roy of The Times of India gave the film 3 out of 5 stars, calling it "strictly watchable, only for the action and spectacle".', 0, 'neu', 'vfx_action');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('war_2_2025', 'Kusumika Das from Times Now gave the film 3 out of 5 stars.', 0, 'neu', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('war_2_2025', 'She praised the performances, action sequences, and dialogues, but noted that the film struggled in the second half due to a slower pace.', -0.25, 'neg', 'acting');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('war_2_2025', 'Vinamra Mathur of Firstpost gave the film 2.5 out of 5 stars and noted that the film had endless conversations and combats that barely served any purpose.', -0.2023, 'neg', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('war_2_2025', 'Rishabh Suri of Hindustan Times gave the film 2 out of 5 stars, criticising the screenplay and soundtrack, but praising the action sequences.', 0.5994, 'pos', 'music');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('war_2_2025', 'Radhika Sharma of NDTV gave 2 out of 5 stars and wrote "The sequel takes the viewers on a journey to at least 10 countries, stuffing episodes from at least six of them in the post credis".', 0, 'neu', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('war_2_2025', 'Mayur Sanap of Rediff.com gave 3.5 out of 5 stars, writing "War 2 offers you exactly what you’d expect from a mass entertainer: some escapist fun, truly knockout action scenes, and overall, a good time at the movies".', 0.7783, 'pos', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('war_2_2025', 'Pranati A S of Deccan Herald gave the film 2 out of 5 stars, criticising the dialogues, story, action sequences, and NTR''s casting, calling his character poorly written and lacking depth.', -0.4019, 'neg', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('war_2_2025', 'Bollywood Hungama gave the film 2 out of 5 stars, criticizing the screenplay as clichéd and unexciting, the direction as subpar, and the editing as dragging.', -0.3612, 'neg', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('war_2_2025', 'Nevertheless, the review highlighted the cinematography, action sequences, production design, and costumes as notable strengths.', 0.4019, 'pos', 'vfx_action');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('war_2_2025', 'Anuj Kumar of The Hindu criticized the direction, noting that Mukerji loses grip on the narrative while balancing the screen time of Roshan and NTR.', -0.5859, 'neg', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('war_2_2025', 'Titas Chowdhury of News18 gave the film 2.5 out of 5 stars, praising the action sequences but criticized the plot and poor execution.', -0.7311, 'neg', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('war_2_2025', 'Rishil Jogani of Pinkvilla gave the film 2.5 out of 5 stars, praising the cinematography, background score, soundtrack, cast performances, production design, and action sequences, but criticised the story and screenplay.', -0.3506, 'neg', 'music');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('war_2_2025', 'Lyca Radio gave 3 out of 5 stars, praising Roshan and NTR''s performances, the action sequences, cinematography, and direction, but criticised the screenplay, and pacing of the second half.', -0.3506, 'neg', 'acting');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('war_2_2025', 'Siddhant Adlakha of Variety wrote "The movie’s attempts at crafting classic action homoeroticism fall dispiritingly flat.', 0, 'neu', 'vfx_action');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('war_2_2025', 'Roshan and NTR’s brooding intensity and muscular physiques may get audiences through the door, but “War 2” has little to keep them excited or engaged".', 0.7717, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('war_2_2025', 'Shubhra Gupta from The Indian Express gave the film 1.5 out of 5 stars, labelling it "a glossy snooze-fest".', 0, 'neu', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('war_2_2025', 'Vineeta Kumar from India Today gave the film 2 out of 5 stars, noting the action as unrealistic and excessive.', 0, 'neu', 'vfx_action');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('war_2_2025', 'She found the plot confused, oscillating between themes of patriotism, friendship, and weak villains.', -0.7717, 'neg', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('war_2_2025', 'Additionally, she considered the background music unimpressive and the songs poorly placed.', -0.34, 'neg', 'music');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('mahavatar_narsimha_2025', 'Mahavatar Narsimha received generally positive reviews from critics who praised the screenplay, music, animation, story and acting but criticized its graphic violence which was deemed too violent in the animation genre.', -0.9253, 'neg', 'music');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('mahavatar_narsimha_2025', 'Ahana Tiwari of Zee News gave 4/5 stars and wrote, "In the end, Mahavatar Narsimha might be far from perfect, yet standing as a quietly confident and emotionally effective film that successfully delivers a deeply moving and devotional cinematic experience.', 0.9399, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('mahavatar_narsimha_2025', 'While not without its flaws, it more than compensates with its heart, message, and the sheer sincerity of its storytelling".', 0.6369, 'pos', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('mahavatar_narsimha_2025', 'Anurag Singh Bohra of India Today rated the film 3.5/5 stars and wrote, "Overall, the film makes for a compelling watch for its emotional relatability and stunning depiction of Narsimha in the goosebump-inducing climax".', 0.6249, 'pos', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('mahavatar_narsimha_2025', 'Susmita Sameera of The Times of India rated it 3/5 stars and wrote, "Mahavatar Narsimha is made with sincerity and ambition.', 0, 'neu', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('mahavatar_narsimha_2025', 'As a first attempt, it lays the groundwork for a promising future in Indian animated devotional cinema.', 0.5994, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('mahavatar_narsimha_2025', 'It is certainly worth experiencing in theatres—for both its pioneering effort and its visual ambition".', 0.5106, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('mahavatar_narsimha_2025', 'Bhawna Arya of Times Now gave 3/5 stars and wrote, "To sum it up, Mahavatar Narsimha by Hombale is an animated film that beautifully and eloquently celebrates the fierceness of Vishnu''s incarnation with breathtaking artistry and heartfelt storytelling".', 0.9313, 'pos', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('mahavatar_narsimha_2025', 'Ganesh Aaglave of Firstpost gave 3/5 stars and wrote, "In the time of larger-than-life action spectacles and rom-coms, experiencing a movie like Mahavatar Narsimha definitely evokes different kinds of positive and holistic emotions".', 0.8316, 'pos', 'vfx_action');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('mahavatar_narsimha_2025', 'Shubhra Gupta of The Indian Express gave 2.5/5 stars and wrote, "The climax is world-class, even if ultra-violent, with body parts and blood flowing generously.', 0.4215, 'pos', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('mahavatar_narsimha_2025', 'Trigger warning for small kids.', -0.34, 'neg', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('mahavatar_narsimha_2025', 'And yourself, if you are faint-hearted.', 0, 'neu', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('mahavatar_narsimha_2025', 'But hey, demons being torn to pieces feels as if justice has been done: our gods really know how to do the Avengers thing".', 0.4767, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('they_call_him_og_2025', 'Divya Shree of The Times of India gave 3/5 stars and wrote "Director Sujeeth leans heavily on star power, often at the cost of layered storytelling and character arcs.', 0, 'neu', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('they_call_him_og_2025', 'Several subplots are undercooked, and familiar tropes such as the wife’s murder and the daughter’s kidnapping feel formulaic. [...] The film has its shortcomings in emotional depth and narrative finesse, but it still succeeds as a stylish action drama with flair." Shrishti Negi of News 18 gave 3/5 stars and wrote "Overall, They Call Him OG is a mass entertainer powered by Pawan Kalyan’s swag.', 0.7311, 'pos', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('they_call_him_og_2025', 'Come for the action and aura, stay for the spectacle but lower expectations on story depth." Swaroop Kodur of The Indian Express gave 3/5 stars and wrote "They Call Him OG is an entertaining film made for hardcore fans, by a hardcore fan himself.', 0.6124, 'pos', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('they_call_him_og_2025', 'Yet, in that pursuit, Sujeeth forgoes the opportunity to take a few risks, and he only goes so far as charming us with his (and his team’s) technical brilliance." Goutham S of Pinkvilla gave 2.5/5 stars and wrote "They Call Him OG is a love letter from a fan to his idol.', 0.9448, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('they_call_him_og_2025', 'Every scene exists to please the inner soul of every fan, and in that regard, it hits the mark.', 0.5574, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('they_call_him_og_2025', 'However, the lack of creativity and originality is evident, leaving little for the general audience to enjoy."
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('they_call_him_og_2025', 'But, beyond those pure theatrical moments, the story remains a familiar and predictable tale about the underworld and gangsters." Neeshita Nyayapati of Hindustan Times gave 2.5/5 stars and wrote "They Call Him OG is a good homage to Pawan’s stardom from Sujeeth, but that doesn’t necessarily mean it’s a good film.', 0.8271, 'pos', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('they_call_him_og_2025', 'You’ve seen this story a million times before, and Ram Gopal Varma definitely did it better in his prime." Sangeetha Devi Dundoo of The Hindu wrote "While the story isn’t new, adding more depth and addressing a few plot holes could have helped.', 0.6808, 'pos', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('they_call_him_og_2025', 'The film relies heavily on the larger-than-life hero trope: OG appears just in time to save loved ones, often in ways that demand more than mere suspension of disbelief. [...] OG aims to tell the story of a Samurai-like hero protecting his people and city, but ultimately, it becomes a film prioritising style and fan service over substance."', 0.8201, 'pos', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('game_changer_2025', 'Rachit Gupta of Filmfare rated the film 3.5/5 and wrote, "In essence, Game Changer is an unmistakable Shankar creation fuelled and delivered with Ram Charan''s charisma." The Hans India also rated the film 3.5 out of 5, calling the performances of Ram Charan and Anjali as "powerhouse" and "strong impact" respectively, and noted, "Game Changer stands out as a solid political drama with exceptional performances, making it a must-watch".', 0.8126, 'pos', 'acting');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('game_changer_2025', 'Paul Nicodemus of The Times of India gave 3/5 stars and wrote, "Overall, Game Changer is a well-executed commercial film.', 0, 'neu', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('game_changer_2025', 'Shankar''s grand scale and Ram Charan''s brilliant performance, combined with strong supporting roles and technical excellence, make it a compelling watch for enthusiasts of the genre".', 0.9657, 'pos', 'acting');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('game_changer_2025', 'The critic also praised the performance of Anjali and S.', 0.2732, 'pos', 'acting');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('game_changer_2025', 'Bollywood Hungama rated the film 3.0/5 and wrote, "Game Changer is yet another mass-appealing anti-corruption saga from Shankar that works due to the clapworthy moments, twists and turns, relatable goings-on and performances of Ram Charan and S.', 0, 'neu', 'acting');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('game_changer_2025', 'Suryah."
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('game_changer_2025', 'Sashidhar Adivi of Times Now gave 3/5 stars and wrote, "With style and swag in abundance, Game Changer is like the quintessential masala entertainer.', 0.6249, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('game_changer_2025', 'The film serves up a little bit of everything in its narrative — action, drama, music, romance, exotic locations and sentiment.', 0.5574, 'pos', 'music');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('game_changer_2025', 'The screenwriting could have been better." Avad Mohammad of OTTplay gave 3/5 stars and wrote, "Ram Charan shines in this social drama that has a predictable plot, narrated in a decent manner."
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('game_changer_2025', 'Now, individually, these segments have a sense of purpose, but together, they sometimes become incoherent due to the lack of focus."
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('game_changer_2025', 'A lot remains the same in this film, which is ironically titled Game Changer."
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('game_changer_2025', 'The film has a second half that is far better than the first, but taken together they do not add up." BVS Prakash of Deccan Chronicle gave 2/5 stars and wrote, "Director Shankar has to give up his old ideas and come back with refreshing story which doesn''t have any shade or resemblance to his earlier blockbusters."
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('game_changer_2025', 'While Ram Charan''s performance is a saving grace, the predictable storyline, over-the-top execution, and lack of originality weigh the film down." Vinamra Mathur of Firstpost gave 2/5 stars and wrote, "In Game Changer, filmmaker Karthik Subbaraj gets the credit for the story.', 0.4767, 'pos', 'acting');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('game_changer_2025', 'Of course, it''s not as unwatchable as Satyameva Jayate 2 or Indian 2, but is that genuinely a compliment?" Neeshita Nyayapati of Hindustan Times wrote, "Game Changer is strictly average, even as you''re rooting for it to be something more.', 0.631, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('game_changer_2025', 'It succeeds in staying focused on what it sets out to do - call out corruption in Indian politics - but gives you nothing more.', 0.4404, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('game_changer_2025', 'And after Shankar''s last outing, Indian 2, maybe that''s a win."', 0.5859, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('kuberaa_2025', 'Avad Mohammad of OTTPlay gave 4/5 stars and wrote "Kuberaa is one of the best Telugu films in recent times.', 0.6369, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('kuberaa_2025', 'With gripping thrills, heartfelt emotions, a compelling story, and a powerful message, the film delivers on every front." Paul Nicodemus of The Times of India gave 3.5/5 stars and wrote "Kuberaa is not your usual commercial potboiler—and that''s precisely what makes it worth a watch.', 0.891, 'pos', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('kuberaa_2025', 'It''s a brooding, introspective take on wealth and morality.', 0.5106, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('kuberaa_2025', 'It''s not flawless, but it''s a bold leap from a filmmaker unafraid to reinvent his canvas." Swaroop Kodur of The Indian Express gave 3.5/5 stars and wrote "Kuberaa wears its bleeding heart on its sleeve for the marginalised, and while several scenes are effective, a few others feel repetitive and yank the pacing.[...] If the bloated duration of the film could be overlooked, Kuberaa stands apart from all the cacophony around as a one-of-a-kind ''mass'' experience." BH Harsh of Cinema Express gave 3.5/5 stars and wrote "Dhanush''s performance, aided by Sekhar''s direction, does wonders here. [...] Kuberaa is a bold stroke of filmmaking, staunch in its commentary and so affecting in its sentiment.', 0.886, 'pos', 'acting');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('kuberaa_2025', 'A few quibbles can be ignored."
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('kuberaa_2025', 'But, it is not one without flaws.', 0, 'neu', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('kuberaa_2025', 'The pre-climax and climax feel a bit rushed and lack emotional connect.', -0.1779, 'neg', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('kuberaa_2025', 'That said, Kuberaa presents a world that will keep you intrigued." Kirubhakar Purushothaman of News18 gave 3/5 stars and wrote "While Kuberaa carefully steers away from the generic nature of commercial entertainers, the end seems like an easy way out and undermines its desire to be unique." Sangeetha Devi Dundoo of The Hindu wrote "Kuberaa falls short of being a gamechanger.', 0.802, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('kuberaa_2025', 'But it is a brave film from a director who has often stepped away from the norm, and raised pertinent questions.', 0.6808, 'pos', 'direction');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('kuberaa_2025', 'That is ample reason to cheer."', 0.5106, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('coolie_2025', 'Coolie received mixed reviews from critics.', -0.296, 'neg', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('coolie_2025', 'Himanshi Tiwari of India TV gave 3.5/5 stars and wrote "Lokesh Kanagaraj, famous for his action films, has once again impressed the audience with the star cast, story and dialogues of this film." S Viswanath of Deccan Herald gave 3.5/5 stars and wrote "By making ‘Coolie’ bloody and gory, Lokesh Kanagaraj has elevated villainy and violence to its full brutal form.', -0.9118, 'neg', 'acting');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('coolie_2025', 'While Rajinikanth lives and walks through his fan-pleasing role, the others play second fiddle to elevate his charisma and screen presence." Rachit Gupta of Filmfare gave 3.5/5 stars and wrote "Coolie does really create a pocket universe of coolness and pulls off the fan service with elan.', 0.7264, 'pos', 'acting');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('coolie_2025', 'It''s not the best dramatic story you''ve ever seen.', -0.5216, 'neg', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('coolie_2025', 'But the moments that unfold on screen are truly entertaining."
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('coolie_2025', 'Bollywood Hungama gave 3/5 stars and wrote "On the whole, Coolie has ample mass moments and swag of Rajinikanth.', 0, 'neu', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('coolie_2025', 'However, the unexciting writing in places act as impediment." Arjun Menon of The Indian Express gave 2.5/5 stars and wrote "Coolie is as much a Rajinikanth film as it is a showcase of the much-celebrated young director’s weakest impulses as an image maker." Saibal Chatterjee of NDTV gave 3/5 stars and wrote "It is Rajinikanth the star and Deva the character who call the shots all the way through."
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('coolie_2025', 'Unfortunately, Coolie is burdened by the weight of its own expectations."
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('coolie_2025', 'It’s a grounded crime action drama with Rajini moments to keep it going.', -0.5423, 'neg', 'vfx_action');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('coolie_2025', 'But if Lokesh’s previous films&nbsp;— like Kaithi, Master, and Vikram&nbsp;— say something that it is that a strong emotional core is the necessary ingredient to make a realistically-shot action drama feel real and present, and this core is what is missing in Coolie." NP Jayaraman of Deccan Herald wrote "While some moments, especially Rajinikanth''s performance, will give audiences goosebumps, the storyline falls flat, making the movie a tedious watch." Rajagopalan Venkataraman of Khaleej Times gave 2.5/5 and wrote "Watch Coolie, but prepare for moments of excitement and disappointment in equal measure.', 0.8968, 'pos', 'acting');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('coolie_2025', 'Dinesh Kumar Maganathan of Free Malaysia Today wrote, "Coolie stands tall as a celebration of Rajinikanth''s golden jubilee in cinema&nbsp;– an entertaining blend of old-school mass moments and modern, layered storytelling".', 0.7351, 'pos', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('good_bad_ugly_2025', 'Good Bad Ugly received mixed reviews from critics, who noted that the film struggled to balance homage and storytelling.', -0.8176, 'neg', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('good_bad_ugly_2025', 'Ganesh Aaglave of Firstpost gave 3.5/5 stars and wrote "On the whole, Good Bad Ugly is a big-ticket entertainer and a visual treat for Thala Ajith fans." M Suganth of The Times of India gave 3/5 stars and wrote "It is cinema of maximalism, often breaking the third wall, peppered with throwbacks, and with only one goal&nbsp;– to deliver a high every few minutes.', 0.1027, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('good_bad_ugly_2025', 'More than mass masala, it''s max masala!" Avinash Ramachandran of The Indian Express gave 3/5 stars and wrote "Even if the writing is shallow, and most of the performances, except an Ajith showreel for the ages, are functional, the film is gloriously engaging."
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('good_bad_ugly_2025', 'It’s a party you can dance through, if you''re in the mood." Bhawana Tanmayi of Moneycontrol gave 2.5/5 stars and wrote "The film completely lacks its main core, which is its storytelling point of view, the lack of emotional core and why we should root for the hero, and, obviously, the film consists of the never-ending slow-motion walks and gunfires.', 0.6808, 'pos', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('good_bad_ugly_2025', 'Anusha Sundar of OTTPlay gave 2.5/5 stars and wrote "GBU is a fanboy cinema, and has its right theatre moments and Easter eggs, if that''s all you want to enjoy a film.', 0.5423, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('good_bad_ugly_2025', 'GBU takes slow to find a pace in its writing.', 0, 'neu', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('good_bad_ugly_2025', 'At times, it fumbles too evidently."
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('good_bad_ugly_2025', 'If you are an ardent Ajith Kumar fan, this will be a treat for you.', 0.7964, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('good_bad_ugly_2025', 'But, if you are expecting even a little bit of a story, you''d be in for disappointment.', -0.6652, 'neg', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('good_bad_ugly_2025', 'Be it dialogues or the staging." Raisa Nasreen of Times Now gave 2.5/5 stars and wrote "Over all, Adhik deliver what they promised fans&nbsp;– a film which is a treat for fans but is a masterclass on good storytelling?"
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('good_bad_ugly_2025', 'From a safe distance, one can argue that it''s the length of a regular movie and it also features a major movie star in the lead.', 0.128, 'pos', 'length');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('good_bad_ugly_2025', 'If you want to push it, one may even argue that it has a something resembling a plot and a screenplay that holds characters and plot points in place." Gopinath Rajendran of The Hindu wrote "Adhik has taken his biggest shot, and it could possibly be the best fan service Tamil cinema has ever seen.', 0.6597, 'pos', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('good_bad_ugly_2025', 'Even when it’s far from perfect and feels like a brass-knuckle punch to our senses, Good Bad Ugly is loving work of nostalgia."', 0.7351, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dragon_2025', 'Dragon received widespread critical acclaim, who praised the performances and engaging storyline.', 0.5106, 'pos', 'acting');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dragon_2025', 'Harshini SV of The Times of India gave 4/5 stars and wrote "''Ashwath Marimuthu''s second outing is also a fun, emotional, and fully charged ride." Kirubhakar Purushothaman of News18 gave 4/5 stars and wrote " The genius of Ashwath''s writing is its thought-out screenplay structure.', 0.4228, 'pos', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dragon_2025', 'It raises despite its predictability.', 0, 'neu', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dragon_2025', 'You see the conflict coming from a mile away.', -0.3182, 'neg', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dragon_2025', 'It is apparent Dragon will get caught; you know the next plot point is right around the corner, and you can feel the redemption arc in the air.', 0, 'neu', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dragon_2025', 'Dragon delivers exactly all that, but in ways you didn''t know were possible." Avinash Ramachandran of The Indian Express gave 3.5/5 stars and wrote "With a terrific Pradeep Ranganathan in the lead, director Ashwath Marimuthu and his team have delivered a heavily preachy yet immensely entertaining film that knows its audience."
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dragon_2025', 'There is enough and more for the audience of today''s age to get entertained and schooled at the same time. [...] Dragon becomes a film on how redemption works." Janani K of India Today gave 3/5 stars and wrote "Dragon is a satisfying watch with minor shortcomings.', 0.6908, 'pos', 'length');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dragon_2025', 'Despite convenient writing, the screenplay keeps the story going with some interesting twists and turns."
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dragon_2025', 'Money is important but is money everything in life?', 0.1027, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dragon_2025', 'Director Ashwath Marimuthu and Pradeep Ranganathan have aced this outing."', 0, 'neu', 'direction');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dude_2025', 'Dude received mixed reviews from critics.', -0.296, 'neg', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dude_2025', 'Roopa Radhakrishnan of The Times of India gave 3/5 stars and wrote "Dude is a confident debut film.', 0.4939, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dude_2025', 'Even though it may not get a lot of things right, the film makes you curious about what its director is going to make next." Janani K of India Today gave 3/5 stars and wrote "Dude'' is a fun-filled film that works best when it embraces its absurdity rather than preach.', 0.7579, 'pos', 'direction');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dude_2025', 'It delivers exactly what it promises – a fun, eccentric romance with moments of genuine hilarity.', 0.8591, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dude_2025', '" Neeshita Nyayapati of Hindustan Times gave 3/5 stars and wrote "If you liked Pradeep’s previous films Love Today (2022) and Dragon (2025), or Mamitha’s Premalu (2024), it’s more than likely that you will like Dude. [...] It doesn’t hurt that their chemistry crackles when they’re together on-screen.', 0.7269, 'pos', 'acting');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dude_2025', 'Dude might not top any of the previously mentioned work of these actors when it comes to the writing, but it’s definitely a good addition to their filmography."
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dude_2025', 'Keerthiswaran’s directorial debut shows promise, blending humour and heart with a socially conscious lens, even if the execution falters in parts.', 0.8625, 'pos', 'direction');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('dude_2025', 'For fans of Pradeep’s brand of quirky charm and those seeking a light-hearted yet meaningful cinematic experience, Dude is well worth a watch."', 0.7906, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('tourist_family_2025', 'Tourist Family received positive reviews from critics, with particular praise for Abishan''s direction and Roldan''s score, as well as the performance of Sasikumar, Simran, Kamalesh and Yogi Babu.', 0.7964, 'pos', 'music');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('tourist_family_2025', 'Anusha Sundar of OTTPlay gave 3.5/5 stars and wrote, "Director Abishan Jeevinth skillfully explores themes of humanity and connection amid adversity, showcasing a diverse ensemble cast that delivers impactful performances." Avinash Ramachandran of The Indian Express gave 3.5/5 stars and wrote, "The Sasikumar-Simran starrer scores heavily on the humour front, and these moments also make you think of how willing audiences are just to forget everything and laugh with a film that also makes them think a lot." Jayabhuvaneshwari B of Cinema Express gave 3.5/5 stars and wrote "A deceptively light film that juggles grief, humour, and warmth in equal measure, powered by Sasikumar''s deeply humane performance and a cast that embodies the messy goodness of everyday people."
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('tourist_family_2025', 'It frames patiently, all the joys and anxieties.', 0.3818, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('tourist_family_2025', 'There is not much movement of the camera".', 0, 'neu', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('su_from_so_2025', 'Su From So received highly positive reviews from critics.', 0.4509, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('su_from_so_2025', 'V. of The Hindu wrote, "‘Su From So’, directed by debutant JP Thuminad and backed by actor-director Raj B Shetty, is helped by witty performances as it becomes a rare horror comedy that seamlessly blends thrills with a pertinent message".', 0.4466, 'pos', 'acting');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('su_from_so_2025', 'Susmita Sameera of The Times of India gave 4/5 and wrote "''Su from So'' emerges as a refreshing entertainer that blends laughter, heartfelt moments, gentle romance, and a powerful message — wrapped in a wholesome package for the entire family to enjoy." A.', 0.9674, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('su_from_so_2025', 'Sharadhaa of The New Indian Express gave 4/5 and wrote "A must-watch, not just for horror or comedy fans, but for anyone who believes cinema can still surprise, subvert, and stay with you." Pranati A.', 0.6596, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('su_from_so_2025', 'S. of Deccan Herald gave 4/5 and wrote "Billed as a horror comedy, the film looks at what real life horror looks like.', -0.5267, 'neg', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('su_from_so_2025', 'And notably, it never for a moment gets dull and preachy." Sanjay Ponnappa of India Today also gave 4/5 and wrote "Directed by JP Thuminad, this Kannada comedy is a fun ride filled with laughter throughout.', 0.8331, 'pos', 'direction');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('su_from_so_2025', 'The film weaves social drama with comedy and presents a beautiful story."', 0.7506, 'pos', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('the_devil_2025', 'The Devil opened with mixed-to-negative reviews from critics.', -0.765, 'neg', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('the_devil_2025', 'The Times of India gave it 2.5 out of 5 stars and wrote, "The Devil is a decent one-time watch for fans of mass cinema- just don''t go in with high expectations." The Indian Express gave it 1.5 out of 5 stars, writing, "The latest film with Darshan, 48, is not only lazy and lacklustre in its writing and execution, but it is also objectionable in the way it treats its women." Vivek MV of The Hindu wrote, "The Devil has a lot to offer for ardent fans.', -0.6243, 'neg', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('the_devil_2025', 'That''s an often-used expression to indirectly sum up a film."
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('the_devil_2025', 'Would you spend 3 hours on an outdated tale that''s far from entertaining and has absolutely nothing by way of USPs?" Sanjay Ponnappa of India Today gave it 1.5 out of 5 stars and wrote, "Overall, the film is such a letdown that there''s barely anything good to say about it.', 0.6728, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('the_devil_2025', 'There are several scenes where the actor pays homage to his people – his "celebrities" – and those moments may offer some satisfaction to die-hard fans.', 0.4404, 'pos', 'acting');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('the_devil_2025', 'For a casual viewer, The Devil can feel like hell for almost three hours."', -0.7717, 'neg', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('lokah_chapter_1_chandra_2025', 'Lokah Chapter 1: Chandra received generally positive reviews from critics.', 0.34, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('lokah_chapter_1_chandra_2025', 'Anandu Suresh of The Indian Express gave 4/5 stars, noting that "What makes the Kalyani Priyadarshan and Naslen-starrer far better than other massive-budget fantasy spectacles is that its magnificence extends beyond visual brilliance to include impeccable writing".', 0.8934, 'pos', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('lokah_chapter_1_chandra_2025', 'Vivek Santhosh of The New Indian Express gave the film 3.5/5 stars, terming it "A bold, imperfect but unforgettable step into Malayalam cinema''s first mythic universe, where Kalyani Priyadarshan''s Chandra embodies folklore, fire, and neon spectacle in a world still finding its full shape".', -0.4497, 'neg', 'vfx_action');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('lokah_chapter_1_chandra_2025', 'Manjusha Radhakrishnan of Gulf News rated 4/5 and wrote, "Superhero saga done right blending Indian folklore with Hollywood swagger."
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('lokah_chapter_1_chandra_2025', 'Ajith of Onmanorama praised Lokah Chapter: 1 Chandra for its "bold" visual design and "immersive" world-building, noting its unique blend of Kerala folklore and the modern-day superhero genre.', 0.7003, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('lokah_chapter_1_chandra_2025', 'Athira M of The Hindu noted that Lokah Chapter: 1 Chandra handles the superhero genre with expertise, praising its "catchy" cinematic quality, visual effects, production design, and background score.', 0.5423, 'pos', 'music');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('lokah_chapter_1_chandra_2025', 'The review highlighted Kalyani Priyadarshan''s performance as "the first female superhero of Malayalam cinema".', 0, 'neu', 'acting');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('l2_empuraan_2025', 'L2: Empuraan received mixed to positive reviews from critics.', 0.34, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('l2_empuraan_2025', 'On the review aggregator website Rotten Tomatoes, 70% of 8 critics'' reviews are positive, with an average rating of 6.2/10.', -0.2263, 'neg', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('l2_empuraan_2025', 'Praveen of The Hindu wrote that "Mohanlal, rich production design fail to save this sequel".', 0.5106, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('l2_empuraan_2025', 'Anna Mathews of Times of India gave 3.5/5 stars and wrote that "L2: Empuraan doesn''t quite match the punch of Lucifer".', 0, 'neu', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('l2_empuraan_2025', 'Ganesh Aaglave of Firstpost gave 3.5/5 stars and wrote "Mohanlal & Prithviraj Sukumaran starrer action-thriller is high on swag, charisma & technical brilliance".', 0.5994, 'pos', 'vfx_action');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('l2_empuraan_2025', 'Pooja Pillai of Eastern Eye wrote that "Despite its storytelling flaws, the film remains a grand theatrical spectacle best experienced on the big screen with all its cinematic flair." Sanjith Sidhardhan of OTTplay gave 3.5/5 stars and wrote "Prithviraj Sukumaran elevates the stakes with an ambitious but less nuanced follow-up to Lucifer".', 0.6858, 'pos', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('l2_empuraan_2025', 'Sajin Shrijith of The Week rated 3/5 and wrote, "The second chapter of ''Lucifer'' is too pre-occupied with eyeball-catching visualisation than storytelling prowess, and suffers a little as a result."
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('l2_empuraan_2025', 'BVS Prakash of Deccan Chronicle gave 2.5/5 stars and wrote that "L2: Empuraan struggles to match the impact of its predecessor but remains an intriguing watch for fans of Lucifer".', -0.1901, 'neg', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('l2_empuraan_2025', 'Janani K of India Today gave 3/5 stars and wrote "Director Prithviraj Sukumaran''s L2: Empuraan is a fitting sequel to Lucifer.', 0, 'neu', 'direction');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('l2_empuraan_2025', 'Mounted on a grand scale, the film displays convenient writing but makes up with stunning visuals." Anandu Suresh of The Indian Express gave 3/5 stars and wrote "Prithviraj Sukumaran''s Mohanlal-starrer is certainly not another run-of-the-mill pan-Indian film that exists solely to scream "look what our star can do!".', 0.6419, 'pos', 'story');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('l2_empuraan_2025', 'Kirubhankar Purushothaman of News18 gave 3.5/5 stars and wrote "Prithviraj Effectively Scales Up Mohanlal''s Lucifer To Greater Heights".', 0.6597, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('l2_empuraan_2025', 'Rohit Panikker of Times Now gave 3.5/5 stars and wrote:"L2: Empuraan is a befitting addition to the Lucifer universe, and entertains you through and through despite its extra run-time and extensive world-building." Bollywood Hungama gave 3/5 stars and wrote "L2: Empuraan boasts mass appeal, grandeur, and stellar performances." Arjun Menon of Rediff gave 3.5/5 stars and wrote "L2: Empuraan is an ambitious sequel that is bigger, bolder and timid in equal measure".', 0.8779, 'pos', 'acting');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('l2_empuraan_2025', 'Pratyusha Sista of Telangana Today wrote "L2: Empuraan is a gripping political thriller that delivers on all fronts—story, action, and performances.', 0.1027, 'pos', 'acting');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('l2_empuraan_2025', 'It''s a well-connected sequel that avoids unnecessary drama, keeping audiences hooked for the entire 180-minute runtime.', -0.1779, 'neg', 'length');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('l2_empuraan_2025', 'Whether you''re a Lucifer fan or a newcomer, this film is a must-watch in theatres for its larger-than-life experience".', 0.3182, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('thudarum_2025', 'Thudarum received positive reviews from critics.', 0.34, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('thudarum_2025', 'Anandu Suresh of The Indian Express gave 4/5 stars and wrote "Tharun Moorthy''s Mohanlal and Shobana-starrer ranks among one of the finest Indian revenge thrillers that hasn''t compromised on any of its aspects, both on the creative and technical sides, while also ensuring brilliant performances".', 0.6705, 'pos', 'acting');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('thudarum_2025', 'Pooja Pillai of Eastern Eye wrote that "Mohanlal returns to form in a dark, emotional ride that''s winning hearts".', 0.8519, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('thudarum_2025', 'S R Praveen of The Hindu wrote, "Thudarum, despite its flaws, is a finely-crafted film with the right emotional beats." Manjusha Radhakrishnan of Gulf News gave 4.5/5 and wrote, "Thudarum comes together as a compelling unit not just because of Mohanlal''s restrained brilliance, but also because of its dark, macabre villains."
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('thudarum_2025', 'Latha Srinivasan of Hindustan Times gave 3.5/5 starts and wrote "A top-form Mohanlal shines in fan boy Tharun Moorthy''s gripping directorial".', 0.3182, 'pos', 'direction');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('thudarum_2025', 'Vignesh Madhu of The New Indian Express gave 3.5/5 and wrote, " Some minor flaws aside, Tharun Moorthy delivers the goods with this finely-crafted film that has the right mix of emotions and high moments." Sanjith Sidharthan of OTTplay rated 4/5 and wrote, "When the Mohanlal-starrer lands in the suspense thriller territory, there''s no holding back.', -0.2023, 'neg', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('thudarum_2025', 'The brilliant casting of Prakash Varma and Binu Pappu further elevates the film"
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('thudarum_2025', 'Shaji Kumar''s cinematography is especially important in a film that dwells, for a good part, in the depths of the woods." Athulya Nambiar of Mid Day wrote, "Shobana brings quiet strength and grace matching Mohanlal''s energy frame for frame while Prakash Varma makes a solid acting debut." Princy Alexander of Onmanorama wrote, "Thudarum is Moorthy''s fanboy service to the actor as evident in some dialogues which also has references to Mammootty and Rajinikanth."', 0.9117, 'pos', 'acting');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('kalamkaval_2025', 'Kalamkaval received positive reviews from critics.', 0.34, 'pos', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('kalamkaval_2025', 'Praveen of The Hindu wrote, "Apart from fine performances from Mammootty and Vinayakan, mind games and character dynamics propel Jithin K Jose’s slow-burn thriller".', 0.5106, 'pos', 'acting');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('kalamkaval_2025', 'Janani K. of India Today rated 3/5 and wrote, "Kalamkaval offers enough twists, strong performances, and atmospheric filmmaking to warrant a watch, even if the runtime tests patience occasionally." Anjana George of The Times of India rated 3/5 and wrote, "Kalamkaval is a film elevated by its lead actors and its atmospheric world, even if the storytelling occasionally falters.', 0.5106, 'pos', 'acting');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('kalamkaval_2025', 'It remains a watch for Mammootty''s enigmatic presence and the unsettling psychological duel at its core.', 0, 'neu', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('kalamkaval_2025', 'Anandu Suresh of The Indian Express rated 2./5 and wrote, "Mammootty once again shows he''s the biggest threat to stardom; but the crime thriller fails him".', -0.8765, 'neg', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('kalamkaval_2025', 'Latha Srinivasan of NDTV rated 3.5/5 and wrote, "Technically, the film is sound with masterly editing, invigorating background and songs, and cinematography.', 0.4767, 'pos', 'music');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('kalamkaval_2025', 'There are numerous artistes who come in various roles but these are not fully explored.', 0, 'neu', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('kalamkaval_2025', 'All in all, it is Mammootty''s highly ''devilish'' act against Vinayakan''s underplayed cop role that makes this a compelling watch.', -0.3597, 'neg', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('kalamkaval_2025', 'Princy Alexander of Onmanorama wrote, " Kalamkaval may not reconstruct the full complexity of a true-crime tale.', 0, 'neu', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('kalamkaval_2025', 'But as a cinematic experience, it delivers a dark, measured, and unnerving output." Sajin Shrijith of The Week rated 4.5/5 and wrote, "An unforgettable Mammootty and a sturdy Vinayakan in a haunting, surprise-laden thriller".', -0.2617, 'neg', 'none');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('kalamkaval_2025', 'Gautham S. of Pinkvilla rated 3.5/5 and highlighted Mammootty''s portrayal but found the narrative predictable.', 0, 'neu', 'acting');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('kalamkaval_2025', 'Rohit Panikker of Filmfare rated 3.5/5 and described it as a slow-burning crime mystery with emphasis on mood and silence.', -0.5423, 'neg', 'length');
INSERT INTO critic_sentences (film_id, sentence_text, vader_compound, sentiment_label, aspect) VALUES ('kalamkaval_2025', 'Vishal Menon of The Hollywood Reporter India stated that Mammootty appeared "like never before" in a genre-driven thriller, praising the film''s atmosphere and its screenwriting.', 0.7506, 'pos', 'story');
